import { MeshBasicNodeMaterial, MeshStandardNodeMaterial, MeshPhysicalNodeMaterial } from 'three/webgpu';
import { uv, vec2, color, float, uniform, mix, smoothstep, abs, max, min, length, sin } from 'three/tsl';
import { gsap } from 'gsap';

export default function createNode(config, ctx) {
  const { Group, Mesh, PlaneGeometry, BoxGeometry, PointLight } = ctx.THREE;

  const COL = {
    background: '#0b0b10',
    surface: '#16161d',
    paper: '#e8ecf2',
    ink: '#16161d',
    accent: '#ff2a38',
    hairline: '#2a2a33',
    rowLine: '#23232b',
    gradTop: '#ff4450',
    gradBot: '#c1121f',
  };

  const items = config.textContent ?? config.intent?.visualSpec?.textContent ?? [];
  const byRole = (role) => items.filter((t) => t && t.role === role);
  const firstText = (role, fallback) => {
    const found = byRole(role)[0];
    return found && typeof found.text === 'string' ? found.text : fallback;
  };

  const root = new Group();
  const geoms = [];
  const mats = [];
  const timelines = [];
  const primHandles = [];

  // ---------------------------------------------------------------- backdrop
  const backdropGeo = new PlaneGeometry(7, 6);
  geoms.push(backdropGeo);
  const backdropMat = new MeshBasicNodeMaterial();
  {
    const bUv = uv();
    const vert = mix(color(COL.background), color(COL.surface), bUv.y.oneMinus().mul(0.85));
    const centerDist = length(bUv.sub(0.5).mul(vec2(1.4, 1.0)));
    const glow = smoothstep(0.15, 0.85, centerDist).oneMinus();
    backdropMat.colorNode = vert.add(color(COL.surface).mul(glow).mul(0.35));
  }
  mats.push(backdropMat);
  const backdrop = new Mesh(backdropGeo, backdropMat);
  backdrop.position.set(0, 0, -2.5);
  root.add(backdrop);

  // ---------------------------------------------------------------- lights (node-local rim/accent)
  const rimLight = new PointLight(COL.accent, 1.1, 14);
  rimLight.position.set(2.8, -1.4, 1.8);
  root.add(rimLight);
  const fillLight = new PointLight(COL.paper, 0.5, 12);
  fillLight.position.set(-3.0, 2.2, 2.4);
  root.add(fillLight);

  // ---------------------------------------------------------------- card
  const CARD_W = 2.4;
  const CARD_H = 3.2;
  const RADIUS = 0.06;
  const PAD = 0.5;
  const LEFT = -CARD_W / 2 + PAD;

  const card = new Group();
  root.add(card);

  const cardGeo = new PlaneGeometry(CARD_W, CARD_H);
  geoms.push(cardGeo);
  const cardMat = new MeshStandardNodeMaterial();
  {
    const p = uv().sub(0.5).mul(vec2(CARD_W, CARD_H));
    const q = abs(p).sub(vec2(CARD_W / 2 - RADIUS, CARD_H / 2 - RADIUS));
    const d = length(max(q, 0.0)).add(min(max(q.x, q.y), 0.0)).sub(RADIUS);
    const alpha = smoothstep(0.0, 0.008, d).oneMinus();
    const borderMask = smoothstep(-0.018, -0.010, d);
    cardMat.colorNode = mix(color(COL.surface), color(COL.hairline), borderMask);
    cardMat.opacityNode = alpha;
    cardMat.transparent = true;
    cardMat.roughnessNode = float(0.6);
    cardMat.metalnessNode = float(0.2);
  }
  mats.push(cardMat);
  const cardMesh = new Mesh(cardGeo, cardMat);
  card.add(cardMesh);

  // ---------------------------------------------------------------- machined header strip
  const stripGeo = new PlaneGeometry(CARD_W - 0.04, 0.08);
  geoms.push(stripGeo);
  const sweepU = uniform(-0.35);
  const stripMat = new MeshPhysicalNodeMaterial();
  {
    const su = uv();
    stripMat.colorNode = color(COL.hairline).mul(float(0.9).add(sin(su.x.mul(600.0)).mul(0.08)));
    stripMat.roughnessNode = float(0.55).add(sin(su.x.mul(600.0)).mul(0.03));
    stripMat.metalnessNode = float(0.5);
    stripMat.clearcoat = 0.2;
    const band = smoothstep(0.0, 0.16, abs(su.x.sub(sweepU))).oneMinus();
    stripMat.emissiveNode = color(COL.paper).mul(band).mul(0.7);
  }
  mats.push(stripMat);
  const strip = new Mesh(stripGeo, stripMat);
  strip.position.set(0, CARD_H / 2 - 0.04, 0.012);
  card.add(strip);

  // ---------------------------------------------------------------- text: tier / price / caption
  const tierText = ctx.fontAtlas.createText(firstText('tier-name', 'ATELIER RESERVE'), {
    fontSize: 20,
    color: COL.paper,
    align: 'left',
    letterSpacingPx: 1.6,
  });
  tierText.position.set(LEFT, 1.08, 0.02);
  card.add(tierText);

  const priceText = ctx.fontAtlas.createText(firstText('price', '$480'), {
    fontSize: 62,
    color: COL.paper,
    align: 'left',
  });
  priceText.position.set(LEFT, 0.66, 0.02);
  card.add(priceText);

  const captionText = ctx.fontAtlas.createText(firstText('caption', 'PER MONTH, BILLED ANNUALLY'), {
    fontSize: 9,
    color: '#9aa2ad',
    align: 'left',
    letterSpacingPx: 1.1,
  });
  captionText.position.set(LEFT, 0.38, 0.02);
  card.add(captionText);

  // ---------------------------------------------------------------- feature rows + hairlines
  const featureItems = byRole('feature');
  const featureStrings = featureItems.length
    ? featureItems.map((f) => f.text)
    : [
        'Quarterly movement service',
        'Priority commission slots',
        'Private fitting lounge access',
        'Lifetime case refinishing',
      ];

  const hairlineGeo = new PlaneGeometry(CARD_W - PAD * 2, 0.006);
  geoms.push(hairlineGeo);
  const hairlineMat = new MeshBasicNodeMaterial();
  hairlineMat.colorNode = color(COL.rowLine);
  mats.push(hairlineMat);

  const tickGeo = new PlaneGeometry(0.045, 0.045);
  geoms.push(tickGeo);
  const tickMat = new MeshBasicNodeMaterial();
  tickMat.colorNode = color(COL.accent);
  mats.push(tickMat);

  const rowStartY = 0.12;
  const rowStep = 0.29;
  const rows = [];
  featureStrings.forEach((str, i) => {
    const row = new Group();
    const y = rowStartY - rowStep * i;
    row.position.set(0, y, 0.02);

    const tick = new Mesh(tickGeo, tickMat);
    tick.position.set(LEFT + 0.02, 0, 0);
    row.add(tick);

    const label = ctx.fontAtlas.createText(String(str), {
      fontSize: 13,
      color: COL.paper,
      align: 'left',
    });
    label.position.set(LEFT + 0.14, 0, 0);
    row.add(label);

    card.add(row);
    rows.push(row);

    if (i < featureStrings.length - 1) {
      const line = new Mesh(hairlineGeo, hairlineMat);
      line.position.set(0, y - rowStep / 2, 0.015);
      card.add(line);
    }
  });
  // hairline above first feature row
  const topLine = new Mesh(hairlineGeo, hairlineMat);
  topLine.position.set(0, rowStartY + rowStep / 2, 0.015);
  card.add(topLine);

  // ---------------------------------------------------------------- CTA row
  const ctaGroup = new Group();
  ctaGroup.position.set(0, -1.24, 0.05);
  card.add(ctaGroup);

  const ctaGeo = new BoxGeometry(1.4, 0.36, 0.05);
  geoms.push(ctaGeo);
  const ctaMat = new MeshStandardNodeMaterial();
  {
    const cu = uv();
    ctaMat.colorNode = mix(color(COL.gradBot), color(COL.gradTop), cu.y);
    const ex = min(cu.x, cu.x.oneMinus()).mul(1.4);
    const ey = min(cu.y, cu.y.oneMinus()).mul(0.36);
    const ring = smoothstep(0.012, 0.032, min(ex, ey)).oneMinus();
    ctaMat.emissiveNode = color(COL.accent).mul(ring).mul(1.5);
    ctaMat.roughnessNode = float(0.5);
    ctaMat.metalnessNode = float(0.15);
  }
  mats.push(ctaMat);
  const ctaMesh = new Mesh(ctaGeo, ctaMat);
  ctaGroup.add(ctaMesh);

  const ctaLabel = ctx.fontAtlas.createText(firstText('cta-label', 'JOIN THE RESERVE'), {
    fontSize: 13,
    color: COL.ink,
    align: 'center',
    letterSpacingPx: 1.1,
  });
  ctaLabel.position.set(0, 0, 0.035);
  ctaGroup.add(ctaLabel);

  // ---------------------------------------------------------------- foreground accent (third depth plane)
  const accentBarGeo = new PlaneGeometry(0.02, 0.9);
  geoms.push(accentBarGeo);
  const accentBarMat = new MeshBasicNodeMaterial();
  accentBarMat.colorNode = color(COL.accent);
  mats.push(accentBarMat);
  const accentBar = new Mesh(accentBarGeo, accentBarMat);
  accentBar.position.set(-1.62, 1.0, 0.45);
  root.add(accentBar);

  // ---------------------------------------------------------------- motion
  const setOpacity = (obj, v) => {
    obj.traverse((o) => {
      if (o.material && 'opacity' in o.material) {
        o.material.transparent = true;
        o.material.opacity = v;
      }
    });
  };

  // weighted settle 1.04 -> 1.0
  const settleTl = gsap.timeline();
  settleTl.fromTo(
    card.scale,
    { x: 1.04, y: 1.04, z: 1.04 },
    { x: 1, y: 1, z: 1, duration: 0.9, ease: 'power4.out' }
  );
  // specular band drag across header during settle
  settleTl.fromTo(sweepU, { value: -0.35 }, { value: 1.35, duration: 0.9, ease: 'power4.out' }, 0);
  timelines.push(settleTl);

  // feature rows stagger fade-up
  const rowTl = gsap.timeline({ delay: 0.15 });
  rows.forEach((row, i) => {
    const baseY = row.position.y;
    const proxy = { v: 0 };
    setOpacity(row, 0);
    rowTl.fromTo(
      row.position,
      { y: baseY - 0.15 },
      { y: baseY, duration: 0.5, ease: 'power2.out' },
      i * 0.08
    );
    rowTl.to(
      proxy,
      { v: 1, duration: 0.5, ease: 'power2.out', onUpdate: () => setOpacity(row, proxy.v) },
      i * 0.08
    );
  });
  timelines.push(rowTl);

  // apply configured primitives (none expected, but honor contract)
  const prims = config.cinematicPrimitives ?? [];
  for (const prim of prims) {
    const fn = ctx.primitives[prim.name];
    if (fn) primHandles.push(fn(card, prim.params ?? {}));
  }

  // ---------------------------------------------------------------- interaction
  let pressTl = null;
  const doPress = () => {
    if (pressTl) pressTl.kill();
    pressTl = gsap.timeline();
    pressTl
      .to(ctaGroup.scale, { x: 0.97, y: 0.97, duration: 0.12, ease: 'power2.out' })
      .to(ctaGroup.scale, { x: 1, y: 1, duration: 0.35, ease: 'back.out(2)' });
    timelines.push(pressTl);
  };

  root.userData.handlers = {
    pointerdown: () => {
      doPress();
    },
    click: () => {
      doPress();
      ctx.emit('cta', { id: 'join-the-reserve', tier: 'atelier-reserve', priceUsd: 480 });
    },
  };

  // ---------------------------------------------------------------- cleanup
  root.userData.cleanup = () => {
    timelines.forEach((tl) => tl && tl.kill());
    primHandles.forEach((h) => h && h.cleanup && h.cleanup());
    geoms.forEach((g) => g.dispose());
    mats.forEach((m) => m.dispose());
    root.traverse((o) => {
      if (o.geometry && !geoms.includes(o.geometry)) o.geometry.dispose();
      if (o.material && !mats.includes(o.material) && o.material.dispose) o.material.dispose();
    });
  };

  return root;
}
